   576→            const wildIndex = total % this.gameState.deck.length;
   577→            this.gameState.wildCard = this.gameState.deck[wildIndex];
   578→            console.log(`亮牌索引超出范围，使用备用计算: ${cardName(this.gameState.wildCard)}`);
   579→        }
   580→
   581→        // 保存抓牌信息用于发牌
   582→        this.gameState.drawInfo = {
   583→            startDirection: secondRollerSeat, // 从第2次掷骰者开始
   584→            drawDirection,
   585→            drawPile,
   586→            totalPiles: total,
