   619→    // 开始发牌（带动画）
   620→    async startDealCards() {
   621→        this.currentRound++;
   622→        this.gameState.roundPhase = 'dealing'; // 发牌阶段
   623→        this.roundReadyPlayers.clear();
   624→
   625→        // 重置玩家准备状态（局间准备用）
   626→        for (const player of this.players.values()) {
   627→            player.ready = false;
   628→        }
   629→
   630→        // 重置每局游戏状态
   631→        this.gameState.discardedPile = [];
   632→        this.gameState.showedCards = {};
   633→        this.gameState.faUsed = {};
   634→        this.gameState.lastDrawn = null;
   635→
   636→        // 初始化手牌
   637→        const playerIds = this.getSortedPlayerIds();
   638→        for (const pid of playerIds) {
   639→            this.gameState.hands[pid] = [];
   640→            this.gameState.showedCards[pid] = { fa: [], gang: [] };
   641→            this.gameState.faUsed[pid] = false;
   642→        }
   643→
   644→        // 根据 drawInfo 计算抓牌起始位置
   645→        const drawInfo = this.gameState.drawInfo;
   646→        let shownCardNewIndex = -1;
   647→
   648→        if (drawInfo && drawInfo.drawDirection) {
   649→            const seatToDirection = { 1: '东', 2: '南', 3: '西', 4: '北' };
   650→            const directionToOffset = { 1: 0, 2: 17, 3: 34, 4: 51 };
   651→            const pileOffset = drawInfo.drawPile - 1;
   652→            let startIndex = (directionToOffset[drawInfo.drawDirection] + pileOffset) * 2;
   653→            startIndex = Math.max(0, Math.min(startIndex, this.gameState.deck.length - 1));
   654→
   655→            const originalShownIndex = this.gameState.shownCardIndex;
   656→            if (originalShownIndex !== undefined && originalShownIndex >= 0) {
   657→                if (originalShownIndex < startIndex) {
   658→                    shownCardNewIndex = this.gameState.deck.length - startIndex + originalShownIndex;
   659→                } else {
   660→                    shownCardNewIndex = originalShownIndex - startIndex;
   661→                }
   662→                console.log(`亮牌原始索引: ${originalShownIndex}, 重排后索引: ${shownCardNewIndex}`);
   663→            }
   664→
   665→            if (startIndex > 0) {
   666→                const before = this.gameState.deck.slice(0, startIndex);
   667→                const after = this.gameState.deck.slice(startIndex);
   668→                this.gameState.deck = [...after, ...before];
   669→                console.log(`牌堆重排，剩余${this.gameState.deck.length}张`);
   670→            }
   671→        }
   672→
   673→        this.gameState.shownCardIndex = shownCardNewIndex;
   674→        this.gameState.wallState = { 1: 17, 2: 17, 3: 17, 4: 17 };
   675→
   676→        // 顺时针发牌顺序
   677→        const clockwiseIds = [
   678→            playerIds[0],
   679→            playerIds[3],
   680→            playerIds[2],
   681→            playerIds[1]
   682→        ];
   683→
   684→        // 辅助函数：抓牌跳过亮牌
   685→        const drawCardSkipShown = () => {
   686→            if (this.gameState.shownCardIndex === this.gameState.deck.length - 1 &&
   687→                !this.gameState.shownCardSkipped) {
   688→                console.log(`跳过亮牌位置`);
   689→                this.gameState.shownCardSkipped = true;
   690→            }
   691→            const card = this.gameState.deck.pop();
   692→            if (!this.gameState.shownCardSkipped && this.gameState.shownCardIndex >= 0) {
   693→                this.gameState.shownCardIndex--;
   694→            }
   695→            return card;
   696→        };
   697→
   698→        // 广播发牌进度的函数
   699→        const broadcastDealProgress = (step, total) => {
   700→            const message = JSON.stringify({
   701→                type: 'dealProgress',
   702→                data: {
   703→                    step,
   704→                    total,
   705→                    hands: Object.fromEntries(
   706→                        Object.entries(this.gameState.hands).map(([pid, cards]) => [pid, cards.length])
   707→                    ),
   708→                    wallState: this.gameState.wallState,
   709→                    deckCount: this.gameState.deck.length
   710→                }
   711→            });
   712→            for (const player of this.players.values()) {
   713→                if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   714→                    player.ws.send(message);
   715→                }
   716→            }
   717→        };
   718→
   719→        // 更新牌墙的函数
   720→        const updateWallForDraw = (count) => {
   721→            // 简化：从最后一个方位开始减少
   722→            let remaining = count;
   723→            for (let dir = 4; dir >= 1 && remaining > 0; dir--) {
   724→                if (this.gameState.wallState[dir] > 0) {
   725→                    const toRemove = Math.min(remaining, this.gameState.wallState[dir]);
   726→                    this.gameState.wallState[dir] -= toRemove;
   727→                    remaining -= toRemove;
   728→                }
   729→            }
   730→        };
   731→
   732→        // 发牌动画：每人4张×3轮
   733→        let dealStep = 0;
   734→        const totalSteps = 3 * 4 + 4 + 1; // 3轮×4人 + 每人1张 + 庄家1张
   735→
   736→        for (let round = 0; round < 3; round++) {
   737→            for (const pid of clockwiseIds) {
   738→                for (let i = 0; i < 4; i++) {
   739→                    const card = drawCardSkipShown();
   740→                    if (card) this.gameState.hands[pid].push(card);
   741→                }
   742→                dealStep++;
   743→                updateWallForDraw(2); // 每次抓2墩
   744→                broadcastDealProgress(dealStep, totalSteps);
   745→                await new Promise(r => setTimeout(r, 150)); // 延迟150ms
   746→            }
   747→        }
   748→
   749→        // 每人1张
   750→        for (const pid of clockwiseIds) {
   751→            const card = drawCardSkipShown();
   752→            if (card) this.gameState.hands[pid].push(card);
   753→            dealStep++;
   754→            updateWallForDraw(1);
   755→            broadcastDealProgress(dealStep, totalSteps);
   756→            await new Promise(r => setTimeout(r, 100));
   757→        }
   758→
   759→        // 庄家多拿1张
   760→        const dealerPid = playerIds[this.gameState.dealer];
   761→        const extraCard = drawCardSkipShown();
   762→        if (extraCard) this.gameState.hands[dealerPid].push(extraCard);
   763→        dealStep++;
   764→        updateWallForDraw(1);
   765→        broadcastDealProgress(dealStep, totalSteps);
   766→
   767→        console.log(`发牌完成，牌堆剩余: ${this.gameState.deck.length}张`);
   768→
   769→        // 更新牌墙状态
   770→        this.updateWallState();
   771→
   772→        // 进入游戏阶段
   773→        this.gameState.roundPhase = 'playing';
   774→        this.gameState.currentPlayer = this.gameState.dealer;
   775→
   776→        // 排序手牌
   777→        for (const pid of playerIds) {
   778→            this.sortHand(pid);
   779→        }
   780→
   781→        console.log(`牌桌${this.tableNumber} 第${this.currentRound}局开始，万能牌: ${cardName(this.gameState.wildCard)}`);
   782→
   783→        // 发送最终游戏状态
   784→        this.broadcastGameState();
   785→        this.checkAITurn();
   786→    }
