   921→    // 排序手牌
   922→    sortHand(playerId) {
   923→        const hand = this.gameState.hands[playerId];
   924→        if (!hand) return;
   925→
   926→        const suitOrder = { '筒': 0, '条': 1, '万': 2, '风': 3, '箭': 4 };
   927→        const windOrder = { '东': 0, '南': 1, '西': 2, '北': 3 };
   928→        const arrowOrder = { '中': 0, '发': 1, '白': 2 };
   929→
   930→        hand.sort((a, b) => {
   931→            // 万能牌放最后
   932→            if (this.isWildCard(a) && !this.isWildCard(b)) return 1;
   933→            if (!this.isWildCard(a) && this.isWildCard(b)) return -1;
   934→
   935→            const suitA = suitOrder[a.suit] ?? 5;
   936→            const suitB = suitOrder[b.suit] ?? 5;
   937→            if (suitA !== suitB) return suitA - suitB;
   938→
   939→            if (a.type === 'number' && b.type === 'number') {
   940→                return a.rank - b.rank;
   941→            } else if (a.type === 'wind' && b.type === 'wind') {
   942→                return (windOrder[a.rank] ?? 0) - (windOrder[b.rank] ?? 0);
   943→            } else if (a.type === 'arrow' && b.type === 'arrow') {
   944→                return (arrowOrder[a.rank] ?? 0) - (arrowOrder[b.rank] ?? 0);
   945→            }
   946→            return 0;
   947→        });
   948→    }
   949→
   950→    // 判断是否是万能牌（相同牌或红中）
   951→    isWildCard(card) {
   952→        const wild = this.gameState.wildCard;
   953→        if (!wild) return false;
   954→
   955→        // 相同牌是万能牌
   956→        if (card.suit === wild.suit && card.rank === wild.rank) return true;
   957→        // 红中也是万能牌
   958→        if (card.type === 'arrow' && card.rank === '中') return true;
   959→
   960→        return false;
   961→    }
