   963→    // 摸牌（跳过亮牌）
   964→    drawCard(playerId) {
   965→        if (this.gameState.deck.length === 0) {
   966→            return null; // 流局
   967→        }
   968→
   969→        // 检查是否遇到亮牌
   970→        if (this.gameState.shownCardIndex === this.gameState.deck.length - 1 &&
   971→            !this.gameState.shownCardSkipped) {
   972→            // 亮牌在牌堆末尾，需要跳过
   973→            console.log(`抓牌时跳过亮牌: ${cardName(this.gameState.shownCard)}`);
   974→            this.gameState.shownCardSkipped = true;
   975→            // 从牌堆移除亮牌（放到牌桌中间显示）
   976→            this.gameState.deck.pop();
   977→            // 更新索引
   978→            this.gameState.shownCardIndex = -1;
