  1032→    // 更新牌墙状态
  1033→    updateWallState() {
  1034→        // 计算已抓取的牌数
  1035→        // 初始136张，如果亮牌已跳过则牌堆少1张亮牌
  1036→        const shownCardRemoved = this.gameState.shownCardSkipped ? 1 : 0;
  1037→        const initialCards = 136 - shownCardRemoved; // 总牌数减去已移除的亮牌
  1038→        const remainingCards = this.gameState.deck.length;
  1039→        const drawnCards = initialCards - remainingCards;
  1040→
  1041→        // 牌墙初始状态：每个方位17墩，都从序号1开始
  1042→        const wallState = {
  1043→            1: { start: 1, count: 17 },  // 南
  1044→            2: { start: 1, count: 17 },  // 西
  1045→            3: { start: 1, count: 17 },  // 北
  1046→            4: { start: 1, count: 17 }   // 东
  1047→        };
  1048→
  1049→        // 根据 drawInfo 确定抓牌起始位置
  1050→        const drawInfo = this.gameState.drawInfo;
  1051→        if (!drawInfo || !drawInfo.drawDirection) {
  1052→            this.gameState.wallState = wallState;
  1053→            return;
  1054→        }
  1055→
  1056→        // 座位映射：1=东, 2=南, 3=西, 4=北
  1057→        // 牌墙方向（逆时针沿牌桌）：东(1) → 南(2) → 西(3) → 北(4) → 东
  1058→        const directionOrder = [1, 2, 3, 4];
  1059→        const seatToDirection = { 1: '东', 2: '南', 3: '西', 4: '北' };
  1060→
  1061→        // 抓牌方向：从序号1往17方向
  1062→
  1063→        const drawDir = drawInfo.drawDirection;
  1064→        const drawIdx = directionOrder.indexOf(drawDir);
  1065→        const startPile = drawInfo.drawPile; // 抓牌起始墩序号（1-17）
  1066→
  1067→        // 计算已抓取的牌墩数（每墩2张）
  1068→        const drawnPiles = Math.floor(drawnCards / 2);
  1069→
  1070→        console.log(`更新牌墙: 已抓${drawnCards}张=${drawnPiles}墩, 抓牌起始${seatToDirection[drawDir]}第${startPile}墩`);
  1071→
  1072→        // 从抓牌起始位置开始，连续抓 drawnPiles 墩
  1073→        // 计算每个方位保留的牌墩
  1074→
  1075→        let remainingToDraw = drawnPiles;
  1076→        let currentDirIdx = drawIdx;
  1077→
  1078→        // 首先处理抓牌方位
  1079→        // 从 startPile 开始到 17，共 (17 - startPile + 1) 墩可抓
  1080→        let availableInDrawDir = 17 - startPile + 1;
  1081→
  1082→        if (remainingToDraw >= availableInDrawDir) {
  1083→            // 抓牌方位的可抓部分全部被抓
  1084→            // 保留序号 1 到 (startPile - 1)
  1085→            wallState[drawDir] = { start: 1, count: startPile - 1 };
  1086→            remainingToDraw -= availableInDrawDir;
  1087→            // 逆时针移动
  1088→            currentDirIdx = (currentDirIdx + 1) % 4;
  1089→        } else {
  1090→            // 只抓了一部分
  1091→            // 保留序号 1 到 (startPile - 1) 和 (startPile + remainingToDraw) 到 17
  1092→            const lastDrawn = startPile + remainingToDraw - 1;
  1093→            if (startPile > 1) {
  1094→                // 前面有保留
  1095→                if (lastDrawn < 17) {
  1096→                    // 后面也有保留
  1097→                    wallState[drawDir] = {
  1098→                        start: 1,
  1099→                        count: startPile - 1,
  1100→                        endKeep: { start: lastDrawn + 1, count: 17 - lastDrawn }
  1101→                    };
  1102→                } else {
  1103→                    // 后面没有保留
  1104→                    wallState[drawDir] = { start: 1, count: startPile - 1 };
  1105→                }
  1106→            } else {
  1107→                // 前面没有保留
  1108→                if (lastDrawn < 17) {
  1109→                    wallState[drawDir] = { start: lastDrawn + 1, count: 17 - lastDrawn };
  1110→                } else {
  1111→                    wallState[drawDir] = { start: 0, count: 0 };
  1112→                }
  1113→            }
  1114→            remainingToDraw = 0;
  1115→        }
  1116→
  1117→        // 逆时针处理其他方位
  1118→        while (remainingToDraw > 0 && currentDirIdx !== drawIdx) {
  1119→            const currentDir = directionOrder[currentDirIdx];
  1120→
  1121→            if (remainingToDraw >= 17) {
  1122→                // 这个方位全部被抓
  1123→                wallState[currentDir] = { start: 0, count: 0 };
  1124→                remainingToDraw -= 17;
  1125→            } else {
  1126→                // 只抓了一部分，从序号1开始抓 remainingToDraw 墩
  1127→                // 保留序号 (remainingToDraw + 1) 到 17
  1128→                wallState[currentDir] = { start: remainingToDraw + 1, count: 17 - remainingToDraw };
  1129→                remainingToDraw = 0;
  1130→            }
  1131→            // 逆时针移动
  1132→            currentDirIdx = (currentDirIdx + 1) % 4;
  1133→        }
  1134→
  1135→        this.gameState.wallState = wallState;
  1136→        console.log(`牌墙状态更新: ${JSON.stringify(wallState)}`);
  1137→    }
