  1207→            !(c.suit === targetCard.suit && c.rank === targetCard.rank)
  1208→        );
  1209→
  1210→        // 加入展示区
  1211→        this.gameState.showedCards[playerId].gang.push(sameCards);
  1212→
  1213→        return sameCards;
