  1479→        // 获取当前玩家的座位号
  1480→        const currentPid = playerIds[this.gameState.currentPlayer];
  1481→        const currentPlayerSeat = this.players.get(currentPid)?.seatNum || 1;
  1482→
  1483→        // 获取庄家的座位号
  1484→        const dealerPid = playerIds[this.gameState.dealer];
  1485→        const dealerSeat = this.players.get(dealerPid)?.seatNum || 1;
  1486→
  1487→        return {
  1488→            started: this.gameState.started,
  1489→            currentPlayer: this.gameState.currentPlayer,
  1490→            currentPlayerSeat,
  1491→            dealer: this.gameState.dealer,
  1492→            dealerSeat,
  1493→            myIndex,
  1494→            myHand,
  1495→            wildCard: this.gameState.wildCard,
  1496→            shownCard: this.gameState.shownCard || null,
  1497→            deckCount: this.gameState.deck.length,
  1498→            totalGameTime: this.gameState.totalGameTime,
  1499→            playerInfo,
  1500→            discardedCount: this.gameState.discardedPile.length,
  1501→            wallState: this.gameState.wallState || { 1: 17, 2: 17, 3: 17, 4: 17 },
  1502→            roundPhase: this.gameState.roundPhase,
  1503→            currentRound: this.currentRound,
  1504→            canChangeFa: this.hasFa(playerId) && this.getCurrentPlayerId() === playerId,
  1505→            canGang: this.canGang(playerId).length > 0 && this.getCurrentPlayerId() === playerId
  1506→        };
  1507→    }
  1508→
  1509→    // 广播消息
  1510→    broadcastMessage(text) {
  1511→        const message = JSON.stringify({ type: 'message', text });
  1512→        for (const player of this.players.values()) {
  1513→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
  1514→                player.ws.send(message);
  1515→            }
  1516→        }
  1517→    }
  1518→
  1519→    // 获取牌桌信息（用于大厅显示）
  1520→    getTableInfo() {
  1521→        return {
  1522→            id: this.id,
  1523→            tableNumber: this.tableNumber,
  1524→            playerCount: this.players.size,
  1525→            maxPlayers: this.maxPlayers,
  1526→            started: this.gameState.started,
  1527→            deckCount: this.gameState.deck ? this.gameState.deck.length : 0,
  1528→            players: Array.from(this.players.values()).map(p => ({
  1529→                name: p.name,
  1530→                seatNum: p.seatNum,
  1531→                ready: p.ready
  1532→            }))
  1533→        };
  1534→    }
  1535→}
  1536→
  1537→// ==================== WebSocket连接处理 ====================
  1538→wss.on('connection', (ws) => {
  1539→    let playerId = null;
  1540→    let playerName = null;
  1541→    let currentTableId = null;
  1542→
  1543→    console.log('新客户端连接');
  1544→
  1545→    ws.on('message', (data) => {
  1546→        try {
  1547→            const msg = JSON.parse(data);
  1548→
  1549→            switch (msg.type) {
  1550→                case 'login':
  1551→                    playerId = `player_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  1552→                    playerName = msg.name || '玩家';
  1553→
  1554→                    // 添加到已登录客户端集合
  1555→                    loggedInClients.add(ws);
  1556→
  1557→                    ws.send(JSON.stringify({
  1558→                        type: 'loginSuccess',
  1559→                        playerId,
  1560→                        playerName
  1561→                    }));
  1562→
  1563→                    // 发送牌桌列表
  1564→                    sendTableList(ws);
  1565→                    break;
  1566→
  1567→                case 'getTableList':
  1568→                    sendTableList(ws);
  1569→                    break;
  1570→
  1571→                case 'createTable':
  1572→                    const newTable = createTable();
  1573→                    // 加入牌桌
  1574→                    if (joinTable(ws, playerId, playerName, newTable.id, msg.seatNum)) {
  1575→                        currentTableId = newTable.id;
  1576→                    }
  1577→                    // 添加AI玩家
  1578→                    const aiCount = msg.aiCount || 0;
  1579→                    for (let i = 0; i < aiCount; i++) {
  1580→                        newTable.addAIPlayer();
  1581→                    }
  1582→                    // 广播牌桌列表更新给所有人
  1583→                    broadcastTableList();
  1584→                    break;
  1585→
  1586→                case 'joinTable':
  1587→                    if (joinTable(ws, playerId, playerName, msg.tableId, msg.seatNum)) {
  1588→                        currentTableId = msg.tableId;
  1589→                        // 广播牌桌列表更新给所有人
  1590→                        broadcastTableList();
  1591→                    }
  1592→                    break;
  1593→
  1594→                case 'ready':
  1595→                    if (currentTableId) {
  1596→                        const table = tables.get(currentTableId);
  1597→                        if (table) {
  1598→                            table.setPlayerReady(playerId, msg.ready);
  1599→                        }
  1600→                    }
  1601→                    break;
  1602→
  1603→                case 'diceRoll':
  1604→                    if (currentTableId) {
  1605→                        const table = tables.get(currentTableId);
  1606→                        if (table && table.diceState.currentRoller === playerId) {
  1607→                            const result = table.rollDice(playerId, msg.values);
  1608→                            if (!result.success) {
  1609→                                ws.send(JSON.stringify({ type: 'error', message: result.message }));
  1610→                            }
  1611→                        }
  1612→                    }
  1613→                    break;
  1614→
  1615→                case 'play':
  1616→                    if (currentTableId) {
  1617→                        const table = tables.get(currentTableId);
  1618→                        if (table && table.getCurrentPlayerId() === playerId) {
  1619→                            if (table.playCard(playerId, msg.cardId)) {
  1620→                                table.broadcastGameState();
  1621→                                // 检查AI出牌
  1622→                                table.checkAITurn();
  1623→                            }
  1624→                        }
  1625→                    }
  1626→                    break;
  1627→
  1628→                case 'changeFa':
  1629→                    if (currentTableId) {
  1630→                        const table = tables.get(currentTableId);
  1631→                        if (table && table.getCurrentPlayerId() === playerId) {
  1632→                            const result = table.changeFa(playerId);
  1633→                            if (result) {
  1634→                                table.broadcastMessage(`${playerName} 换了一张"發"`);
  1635→                                table.broadcastGameState();
  1636→                            }
  1637→                        }
  1638→                    }
  1639→                    break;
  1640→
  1641→                case 'gang':
  1642→                    if (currentTableId) {
  1643→                        const table = tables.get(currentTableId);
  1644→                        if (table && table.getCurrentPlayerId() === playerId) {
  1645→                            const result = table.doGang(playerId, msg.cardId);
  1646→                            if (result) {
  1647→                                table.broadcastMessage(`${playerName} 暗杠！`);
  1648→                                table.broadcastGameState();
  1649→                            }
  1650→                        }
  1651→                    }
  1652→                    break;
  1653→
  1654→                case 'draw':
  1655→                    if (currentTableId) {
  1656→                        const table = tables.get(currentTableId);
  1657→                        if (table && table.getCurrentPlayerId() === playerId) {
  1658→                            const card = table.drawCard(playerId);
  1659→                            if (card) {
  1660→                                table.broadcastGameState();
  1661→                            } else {
  1662→                                table.broadcastMessage('牌堆已空，流局！');
  1663→                            }
  1664→                        }
  1665→                    }
  1666→                    break;
  1667→
  1668→                case 'chat':
  1669→                    if (currentTableId) {
  1670→                        const table = tables.get(currentTableId);
  1671→                        if (table) {
  1672→                            table.broadcastMessage(`${playerName}: ${msg.text}`);
  1673→                        }
  1674→                    }
  1675→                    break;
  1676→            }
  1677→        } catch (e) {
  1678→            console.error('消息处理错误:', e);
  1679→        }
  1680→    });
  1681→
  1682→    ws.on('close', () => {
  1683→        console.log('客户端断开:', playerName);
  1684→
  1685→        // 从已登录客户端集合中移除
  1686→        loggedInClients.delete(ws);
  1687→
  1688→        if (currentTableId && playerId) {
  1689→            const table = tables.get(currentTableId);
  1690→            if (table) {
  1691→                // 标记玩家断开
  1692→                const player = table.players.get(playerId);
  1693→                if (player) {
  1694→                    player.ws = null;
  1695→                    player.ready = false;
  1696→                }
  1697→
  1698→                // 如果游戏未开始，直接移除玩家
  1699→                if (!table.gameState.started) {
  1700→                    table.removePlayer(playerId);
  1701→                }
  1702→
  1703→                // 检查是否所有玩家都已断开连接，如果是则删除房间
  1704→                if (table.isAllPlayersDisconnected()) {
  1705→                    tables.delete(currentTableId);
  1706→                    console.log(`牌桌 ${currentTableId} 所有人已离开，自动解散`);
  1707→                } else {
  1708→                    table.broadcastPlayerList();
  1709→                }
  1710→            }
  1711→            playerToTable.delete(playerId);
  1712→
  1713→            // 广播牌桌列表更新（因为有人离开）
  1714→            broadcastTableList();
  1715→        }
  1716→    });
  1717→});
  1718→
  1719→// 发送牌桌列表
  1720→function sendTableList(ws) {
  1721→    const tableList = Array.from(tables.values()).map(t => t.getTableInfo());
  1722→    ws.send(JSON.stringify({
  1723→        type: 'tableList',
  1724→        tables: tableList
  1725→    }));
  1726→}
  1727→
  1728→// 广播牌桌列表给所有已登录客户端
  1729→function broadcastTableList() {
  1730→    const tableList = Array.from(tables.values()).map(t => t.getTableInfo());
  1731→    const message = JSON.stringify({
  1732→        type: 'tableList',
  1733→        tables: tableList
  1734→    });
  1735→
  1736→    // 广播给所有连接的客户端
  1737→    let count = 0;
  1738→    wss.clients.forEach(client => {
  1739→        if (client.readyState === WebSocket.OPEN) {
  1740→            client.send(message);
  1741→            count++;
  1742→        }
  1743→    });
  1744→    console.log(`广播牌桌列表给 ${count} 个客户端，当前牌桌数: ${tableList.length}`);
  1745→}
  1746→
  1747→// 创建牌桌
  1748→function createTable() {
  1749→    tableCounter++;
  1750→    const tableId = `table_${tableCounter}`;
  1751→    const table = new GameTable(tableId, tableCounter);
  1752→    tables.set(tableId, table);
  1753→    console.log(`创建新牌桌: ${tableId}`);
  1754→    return table;
  1755→}
  1756→
  1757→// 加入牌桌
  1758→function joinTable(ws, playerId, playerName, tableId, seatNum) {
  1759→    const table = tables.get(tableId);
  1760→    if (!table) {
  1761→        ws.send(JSON.stringify({ type: 'error', message: '牌桌不存在' }));
  1762→        return false;
  1763→    }
  1764→
  1765→    if (table.addPlayer(ws, playerId, playerName, seatNum)) {
  1766→        playerToTable.set(playerId, tableId);
  1767→        table.broadcastPlayerList();
  1768→        console.log(`${playerName} 加入牌桌 ${tableId}`);
  1769→        return true;
  1770→    } else {
  1771→        ws.send(JSON.stringify({ type: 'error', message: '无法加入牌桌（已满或游戏已开始）' }));
  1772→        return false;
  1773→    }
  1774→}
  1775→
  1776→// 获取本机IP
  1777→function getLocalIP() {
  1778→    const os = require('os');
  1779→    const interfaces = os.networkInterfaces();
  1780→
  1781→    for (const name of Object.keys(interfaces)) {
  1782→        for (const iface of interfaces[name]) {
  1783→            if (iface.family === 'IPv4' && !iface.internal) {
  1784→                return iface.address;
  1785→            }
  1786→        }
  1787→    }
  1788→    return 'localhost';
  1789→}
  1790→
  1791→// 启动服务器
  1792→server.listen(PORT, () => {
  1793→    const localIP = getLocalIP();
  1794→    console.log('');
  1795→    console.log('Majiang Server Started!');
  1796→    console.log(`Game URL: http://localhost:${PORT}`);
  1797→    console.log(`LAN URL: http://${localIP}:${PORT}`);
  1798→    console.log('');
  1799→});
  1800→
  1801→// 定时清理空桌子（每5分钟检查一次）
  1802→setInterval(() => {
  1803→    for (const [tableId, table] of tables) {
  1804→        // 如果桌子没有玩家，或者所有玩家都已断开连接
  1805→        if (table.players.size === 0) {
