// 广播发牌进度的函数
const broadcastDealProgress = (step, total) => {
    const message = JSON.stringify({
        type: 'dealProgress',
        data: {
            step,
            total,
            hands: Object.fromEntries(
                Object.entries(this.gameState.hands).map(([pid, cards]) => [pid, cards.length])
            ),
            wallState: this.gameState.wallState,
            deckCount: this.gameState.deck.length
        }
    });
    for (const player of this.players.values()) {
        if (player.ws && player.ws.readyState === WebSocket.OPEN) {
            player.ws.send(message);
        }
    }
};

// 更新牌墙的函数
const updateWallForDraw = (count) => {
    // 简化：从最后一个方位开始减少
    let remaining = count;
    for (let dir = 4; dir >= 1 && remaining > 0; dir--) {
        if (this.gameState.wallState[dir] > 0) {
            const toRemove = Math.min(remaining, this.gameState.wallState[dir]);
            this.gameState.wallState[dir] -= toRemove;
            remaining -= toRemove;
        }
    }
};

