// 桐城自摸麻将 - 局域网服务器
// 运行方式: node majiang-server.js

const http = require('http');
const fs = require('fs');
const path = require('path');
const WebSocket = require('ws');

const PORT = 8082;

// ==================== HTTP服务器 ====================
const server = http.createServer((req, res) => {
    console.log(`HTTP请求: ${req.url}`);

    // 解码URL（处理中文文件名）
    const decodedUrl = decodeURIComponent(req.url);

    if (req.url === '/' || req.url === '/index.html') {
        const htmlPath = path.join(__dirname, 'majiang-lan.html');
        fs.readFile(htmlPath, (err, data) => {
            if (err) {
                res.writeHead(404);
                res.end('游戏文件未找到');
                return;
            }
            res.writeHead(200, {
                'Content-Type': 'text/html; charset=utf-8'
            });
            res.end(data);
        });
    } else if (req.url === '/favicon.ico') {
        res.writeHead(204);
        res.end();
    } else if (decodedUrl.endsWith('.jpg') || decodedUrl.endsWith('.jpeg') || decodedUrl.endsWith('.png') || decodedUrl.endsWith('.gif')) {
        // 处理图片文件
        const imagePath = path.join(__dirname, decodedUrl);
        fs.readFile(imagePath, (err, data) => {
            if (err) {
                console.log(`图片未找到: ${imagePath}`);
                res.writeHead(404);
                res.end('图片未找到');
                return;
            }
            const ext = path.extname(decodedUrl).toLowerCase();
            const contentTypes = {
                '.jpg': 'image/jpeg',
                '.jpeg': 'image/jpeg',
                '.png': 'image/png',
                '.gif': 'image/gif'
            };
            res.writeHead(200, {
                'Content-Type': contentTypes[ext] || 'application/octet-stream'
            });
            res.end(data);
        });
    } else {
        res.writeHead(404);
        res.end('Not Found');
    }
});

// ==================== WebSocket服务器 ====================
const wss = new WebSocket.Server({ server });

// 游戏房间管理
const tables = new Map();
const playerToTable = new Map();
let tableCounter = 0;

// 所有已登录的客户端（用于广播牌桌列表）
const loggedInClients = new Set();

// ==================== 牌面常量 ====================
const SUITS = ['筒', '条', '万'];
const RANKS = [1, 2, 3, 4, 5, 6, 7, 8, 9];
const WINDS = ['东', '南', '西', '北'];
const ARROWS = ['中', '发', '白'];

// 创建一副麻将牌
function createDeck() {
    const deck = [];

    // 筒条万 (每种4张)
    for (const suit of SUITS) {
        for (const rank of RANKS) {
            for (let i = 0; i < 4; i++) {
                deck.push({
                    suit,
                    rank,
                    type: 'number',
                    id: `${suit}${rank}_${i}`
                });
            }
        }
    }

    // 风牌 (每种4张)
    for (const wind of WINDS) {
        for (let i = 0; i < 4; i++) {
            deck.push({
                suit: '风',
                rank: wind,
                type: 'wind',
                id: `风${wind}_${i}`
            });
        }
    }

    // 箭牌 (每种4张)
    for (const arrow of ARROWS) {
        for (let i = 0; i < 4; i++) {
            deck.push({
                suit: '箭',
                rank: arrow,
                type: 'arrow',
                id: `箭${arrow}_${i}`
            });
        }
    }

    return deck; // 136张
}

// 洗牌
function shuffle(deck) {
    const shuffled = [...deck];
    for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
}

// 牌的显示名称
function cardName(card) {
    if (card.type === 'number') {
        return `${card.rank}${card.suit}`;
    } else {
        return card.rank;
    }
}

// ==================== 牌桌类 ====================
class GameTable {
    constructor(id, tableNumber) {
        this.id = id;
