        } else if (this.gameState.roundPhase === 'ended') {
            // 局间准备，检查所有人是否都准备了
            const allRoundReady = this.roundReadyPlayers.size === this.players.size;
            if (allRoundReady) {
                this.startDicePhase();
            }
        }
    }

    // 开始掷骰子阶段
    startDicePhase() {
        // 先初始化牌堆和庄家
        this.initDeckAndDealer();

        this.gameState.roundPhase = 'dice';
        this.diceState = {
            firstRoll: null,
