    // 获取第一次掷骰子的人
    getFirstRoller() {
        const playerIds = this.getSortedPlayerIds();
        // 座位映射：1=东(庄家), 2=南, 3=西, 4=北

        if (this.currentRound === 0) {
            // 周期第一局：东边玩家（座位1）掷骰子
