        // 逆时针顺序：东(0)→北(3)→西(2)→南(1)→东(0)
        // 逆时针移动一步 = 索引 -1（或 +3 mod 4）
        // 数firstSum步，从1开始数（所以-1）
        const secondRollerIndex = (firstRollerIndex - (firstSum - 1) % 4 + 4) % 4;
