            // 检查是否轮到AI掷第二次骰子
            setTimeout(() => this.checkAITurn(), 500);

            return { success: true, phase: 1, values };

        } else if (this.diceState.rollPhase === 2) {
            // 第二次掷骰子
            this.diceState.secondRoll = { playerId, playerName: player.name, values };
            this.diceState.rollPhase = 3;

