/* 展示区 */
.showed-area {
    display: flex;
    gap: 5px;
    margin: 5px 0;
    flex-wrap: wrap;
    justify-content: center;
}

.showed-card {
    width: 30px;
    height: 40px;
    background: #fff;
    border-radius: 3px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    color: #333;
    overflow: hidden;
}

.showed-card.fa {
    background: #FFD700;
}

.showed-card.gang {
    background: #90EE90;
}

/* 对手手牌背面 */
.opponent-hand {
    display: flex;
    gap: 2px;
    justify-content: center;
    margin: 5px 0;
    min-height: 30px;
}

.opponent-card-back {
    width: 20px;
    height: 28px;
    background: linear-gradient(135deg, #2c5530 0%, #1a3a1f 100%);
    border: 1px solid #3d6b42;
    border-radius: 2px;
    box-shadow: 1px 1px 2px rgba(0,0,0,0.3);
}

