.opponent-card-back {
    width: 20px;
    height: 28px;
    background: linear-gradient(135deg, #2c5530 0%, #1a3a1f 100%);
    border: 1px solid #3d6b42;
    border-radius: 2px;
    box-shadow: 1px 1px 2px rgba(0,0,0,0.3);
}

/* 弃牌区域 */
.discarded-area {
    display: flex;
    flex-wrap: wrap;
    gap: 1px;
    justify-content: center;
    margin: 5px 0;
    min-height: 35px;
    max-width: 200px;
}

.discarded-card {
    width: 18px;
    height: 24px;
    background: linear-gradient(135deg, #2c5530 0%, #1a3a1f 100%);
    border: 1px solid #3d6b42;
    border-radius: 2px;
    box-shadow: 1px 1px 2px rgba(0,0,0,0.3);
    margin-left: -8px; /* 叠放效果 */
}

.discarded-card:first-child {
    margin-left: 0;
}

/* 每五张换行 */
.discarded-card:nth-child(5n+1) {
    margin-left: 0;
}

