// 判断是否是万能牌（相同牌或红中）
isWildCard(card) {
    const wild = this.gameState.wildCard;
    if (!wild) return false;

    // 相同牌是万能牌
    if (card.suit === wild.suit && card.rank === wild.rank) return true;
    // 红中也是万能牌
    if (card.type === 'arrow' && card.rank === '中') return true;

    return false;
}

